/** Canonical UUID text form (any version), case-insensitive. */
export const UUID_PATTERN =
  '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';

const uuidRegExp = new RegExp(UUID_PATTERN);

export function isUuid(value: string): boolean {
  return uuidRegExp.test(value);
}

src/shared/kernel/compare.ts.source:
/**
 * Orders strings by code point, like PostgreSQL's `C` collation, so the
 * in-memory and database stages sort text the same way.
 */
export function compareText(a: string, b: string): number {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

